"use client";

import { useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Dialog,
	DialogClose,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
	DialogTrigger,
} from "@/components/ui/dialog";
import { OTPInput, SlotProps } from "input-otp";

import { cn } from "@/lib/utils";

const CORRECT_CODE = "6548";

export default function Component() {
	const [value, setValue] = useState("");
	const [hasGuessed, setHasGuessed] = useState<undefined | boolean>(undefined);
	const inputRef = useRef<HTMLInputElement>(null);
	const closeButtonRef = useRef<HTMLButtonElement>(null);

	useEffect(() => {
		if (hasGuessed) {
			closeButtonRef.current?.focus();
		}
	}, [hasGuessed]);

	async function onSubmit(e?: React.FormEvent<HTMLFormElement>) {
		e?.preventDefault?.();

		inputRef.current?.select();
		await new Promise((r) => setTimeout(r, 1_00));

		setHasGuessed(value === CORRECT_CODE);

		setValue("");
		setTimeout(() => {
			inputRef.current?.blur();
		}, 20);
	}

	return (
		<Dialog>
			<DialogTrigger asChild>
				<Button variant="outline">OTP code</Button>
			</DialogTrigger>
			<DialogContent>
				<div className="flex flex-col items-center gap-2">
					<div
						className="flex size-11 shrink-0 items-center justify-center rounded-full border"
						aria-hidden="true"
					>
						<svg
							className="stroke-zinc-800 dark:stroke-zinc-100"
							xmlns="http://www.w3.org/2000/svg"
							width="20"
							height="20"
							viewBox="0 0 32 32"
							aria-hidden="true"
						>
							<circle
								cx="16"
								cy="16"
								r="12"
								fill="none"
								strokeWidth="8"
							/>
						</svg>
					</div>
					<DialogHeader>
						<DialogTitle className="sm:text-center">
							{hasGuessed ? "Code verified!" : "Enter confirmation code"}
						</DialogTitle>
						<DialogDescription className="sm:text-center">
							{hasGuessed
								? "Your code has been successfully verified."
								: `Check your email and enter the code - Try ${CORRECT_CODE}`}
						</DialogDescription>
					</DialogHeader>
				</div>

				{hasGuessed ? (
					<div className="text-center">
						<DialogClose asChild>
							<Button type="button" ref={closeButtonRef}>
								Close
							</Button>
						</DialogClose>
					</div>
				) : (
					<div className="space-y-4">
						<div className="flex justify-center">
							<OTPInput
								id="cofirmation-code"
								ref={inputRef}
								value={value}
								onChange={setValue}
								containerClassName="flex items-center gap-3 has-disabled:opacity-50"
								maxLength={4}
								onFocus={() => setHasGuessed(undefined)}
								render={({ slots }) => (
									<div className="flex gap-2">
										{slots.map((slot, idx) => (
											<Slot key={idx} {...slot} />
										))}
									</div>
								)}
								onComplete={onSubmit}
							/>
						</div>
						{hasGuessed === false && (
							<p
								className="text-muted-foreground text-center text-xs"
								role="alert"
								aria-live="polite"
							>
								Invalid code. Please try again.
							</p>
						)}
						<p className="text-center text-sm">
							<a className="underline hover:no-underline" href="#">
								Resend code
							</a>
						</p>
					</div>
				)}
			</DialogContent>
		</Dialog>
	);
}

function Slot(props: SlotProps) {
	return (
		<div
			className={cn(
				"border-input bg-background text-foreground flex size-9 items-center justify-center rounded-md border font-medium shadow-2xs transition-[color,box-shadow]",
				{ "border-ring ring-ring/50 z-10 ring-[3px]": props.isActive }
			)}
		>
			{props.char !== null && <div>{props.char}</div>}
		</div>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };
